import React, { useEffect, useState } from "react";
import axios from "axios";
import RefundAnalytics from "./components/RefundAnalytics";
import AdminSidebar from "../../components/AdminSidebar";
import NexaAuthWrapper from "./components/NexaAuthWrapper";

const API = "http://localhost:8000";

export default function NexaLive() {
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [sessions, setSessions] = useState([]);
  const [selected, setSelected] = useState(null);
  const [loading, setLoading] = useState(false);
  const [suggestion, setSuggestion] = useState(null);
  const [overrideAmount, setOverrideAmount] = useState("");
  const [agentId] = useState("admin_main"); // In production, get from auth

  useEffect(() => {
    fetchSessions();
    const interval = setInterval(fetchSessions, 10000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (selected) {
        setSuggestion(null);
        setOverrideAmount("");
    }
  }, [selected]);

  async function fetchSessions() {
    const token = localStorage.getItem("nexa_token");
    if (!token) return;
    try {
      const r = await axios.get(`${API}/api/live/sessions`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setSessions(r.data);
    } catch {}
  }

  async function getSuggestion() {
    if (!selected) return;
    const token = localStorage.getItem("nexa_token");
    if (!token) return;
    setLoading(true);
    try {
      const r = await axios.post(`${API}/api/live/refund/suggest`, 
        {
          ticket_id: selected.id, agent_id: agentId,
          anger_score: selected.anger_score, anger_level: selected.anger_level,
          intent: selected.intent, compensation_type: selected.compensation_type || "store_credit",
          order_value: 50.0 // Mock order value for demo
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setSuggestion(r.data);
      setOverrideAmount(r.data.ai_amount.toString());
    } catch {
      alert("AI suggestion failed. Check backend logs.");
    } finally {
      setLoading(false);
    }
  }

  async function executeRefund(action) {
    if (!suggestion) return;
    const token = localStorage.getItem("nexa_token");
    if (!token) return;
    setLoading(true);
    try {
      await axios.post(`${API}/api/live/refund/approve`, 
        {
          refund_audit_id: suggestion.audit_id, agent_id: agentId,
          final_amount: parseFloat(overrideAmount) || suggestion.ai_amount,
          final_type: suggestion.ai_type,
          override_reason: parseFloat(overrideAmount) !== suggestion.ai_amount ? "Agent adjusted amount" : null,
          action
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      alert(`Refund ${action}ed successfully!`);
      setSuggestion(null);
      setSelected(null);
      fetchSessions();
    } catch {
      alert("Failed to process refund.");
    } finally {
      setLoading(false);
    }
  }

  const body = () => (
    <div className="animate-fade-in" style={{ padding: "2rem" }}>
      <div style={{ marginBottom: "2.5rem" }}>
        <p style={{ color: "var(--color-text-muted)", fontSize: "0.85rem", marginBottom: "0.4rem" }}>HUMAN-IN-THE-LOOP CONTROL</p>
        <h1 style={{ fontFamily: "'Space Grotesk', sans-serif", fontWeight: 700, fontSize: "2rem" }}>
          Live <span className="gradient-text">Command Center</span>
        </h1>
      </div>

      <div style={{ marginBottom: "2rem" }}>
        <RefundAnalytics />
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "380px 1fr", gap: "1.5rem", alignItems: "start" }}>
        {/* Session List */}
        <div className="glass" style={{ borderRadius: 24, padding: "1.5rem", minHeight: "65vh" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1.5rem" }}>
             <h3 style={{ fontSize: "0.9rem", fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.05em" }}>Live Queue</h3>
             <span style={{ fontSize: "0.75rem", background: "rgba(16,185,129,0.1)", color: "#10b981", padding: "0.2rem 0.5rem", borderRadius: 20, fontWeight: 700 }}>{sessions.length} Active</span>
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: "0.75rem" }}>
            {sessions.map(s => (
              <div 
                key={s.id} 
                className={`glass-hover ${selected?.id === s.id ? 'active-glow' : ''}`}
                style={{ 
                  padding: "1rem", 
                  borderRadius: 16, 
                  cursor: "pointer", 
                  background: selected?.id === s.id ? "rgba(99, 102, 241, 0.05)" : "rgba(0,0,0,0.01)",
                  border: `1px solid ${selected?.id === s.id ? "rgba(99, 102, 241, 0.2)" : "var(--color-border)"}`
                }}
                onClick={() => setSelected(s)}
              >
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "0.5rem" }}>
                  <span style={{ fontSize: "0.7rem", fontWeight: 700, color: "var(--color-text-dim)", textTransform: "uppercase" }}>Ticket #{s.id.slice(-5)}</span>
                  <span style={{ fontSize: "0.65rem", color: s.anger_level === "ANGRY" ? "#ef4444" : "#10b981", fontWeight: 800 }}>{s.anger_level}</span>
                </div>
                <p style={{ fontSize: "0.85rem", fontWeight: 500, color: "var(--color-text)", marginBottom: "0.5rem", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{s.raw_message}</p>
                <div style={{ display: "flex", gap: "0.5rem" }}>
                    <span style={{ fontSize: "0.65rem", background: "var(--color-surface-2)", padding: "0.2rem 0.5rem", borderRadius: 4, fontWeight: 600 }}>{s.intent}</span>
                </div>
              </div>
            ))}
            {sessions.length === 0 && <p style={{ textAlign: "center", color: "var(--color-text-dim)", fontSize: "0.85rem", marginTop: "2rem" }}>No active sessions.</p>}
          </div>
        </div>

        {/* Intelligence Pane */}
        <div className="glass" style={{ borderRadius: 24, padding: "2rem", minHeight: "65vh" }}>
          {!selected ? (
            <div style={{ height: "100%", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", color: "var(--color-text-dim)" }}>
                <span style={{ fontSize: "3rem", marginBottom: "1.5rem" }}>🎯</span>
                <p style={{ fontWeight: 500 }}>Select a ticket from the queue to begin AI-assisted resolution.</p>
            </div>
          ) : (
            <div className="animate-fade-in">
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: "2rem" }}>
                 <div>
                    <h2 style={{ fontSize: "1.25rem", fontWeight: 700, marginBottom: "0.25rem" }}>Session Analysis</h2>
                    <p style={{ fontSize: "0.85rem", color: "var(--color-text-muted)" }}>Agent UUID: {agentId}</p>
                 </div>
                 <div style={{ textAlign: "right" }}>
                    <div style={{ fontSize: "0.75rem", fontWeight: 700, color: "var(--color-text-muted)", marginBottom: "0.35rem" }}>CUSTOMER SENTIMENT</div>
                    <div style={{ fontSize: "1.5rem", fontWeight: 700, color: selected.anger_level === "ANGRY" ? "#ef4444" : "#10b981" }}>{(selected.anger_score * 100).toFixed(0)}% <span style={{ fontSize: "0.9rem", fontWeight: 600 }}>{selected.anger_level}</span></div>
                 </div>
              </div>

              <div style={{ background: "#ffffff", borderRadius: 16, padding: "1.5rem", marginBottom: "2rem", border: "1px solid var(--color-border)" }}>
                 <p style={{ fontSize: "0.75rem", color: "var(--color-text-dim)", fontWeight: 700, marginBottom: "0.75rem", textTransform: "uppercase" }}>Raw Customer Input</p>
                 <p style={{ fontSize: "1rem", lineHeight: 1.6, color: "var(--color-text)", fontStyle: "italic" }}>&ldquo;{selected.raw_message}&rdquo;</p>
              </div>

              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "1.5rem", marginBottom: "2rem" }}>
                 <div className="glass" style={{ padding: "1.25rem", borderRadius: 16 }}>
                    <p style={{ fontSize: "0.7rem", color: "var(--color-text-dim)", fontWeight: 700, marginBottom: "0.5rem" }}>DETECTED INTENT</p>
                    <p style={{ fontSize: "1.1rem", fontWeight: 700, color: "var(--color-primary)" }}>{selected.intent.replace(/_/g, " ")}</p>
                 </div>
                 <div className="glass" style={{ padding: "1.25rem", borderRadius: 16 }}>
                    <p style={{ fontSize: "0.7rem", color: "var(--color-text-dim)", fontWeight: 700, marginBottom: "0.5rem" }}>PROPOSED ACTION</p>
                    <p style={{ fontSize: "1.1rem", fontWeight: 700, color: "#10b981" }}>{selected.compensation_type?.toUpperCase() || "NONE"}</p>
                 </div>
              </div>

              {/* AI Recommendation Section */}
              <div style={{ borderTop: "1px solid var(--color-border)", paddingTop: "2rem" }}>
                 {!suggestion ? (
                    <div style={{ textAlign: "center" }}>
                        <button className="btn-primary" onClick={getSuggestion} disabled={loading} style={{ padding: "1rem 2.5rem" }}>
                            {loading ? "Generating Recommendation..." : "Generate AI Refund Suggestion"}
                        </button>
                        <p style={{ fontSize: "0.8rem", color: "var(--color-text-dim)", marginTop: "1rem" }}>Inference runs on local neural core (100% Secure)</p>
                    </div>
                 ) : (
                    <div className="animate-fade-in glass" style={{ padding: "2rem", borderRadius: 20, border: "2px solid rgba(99, 102, 241, 0.3)" }}>
                        <h3 style={{ fontSize: "1rem", fontWeight: 700, marginBottom: "1.5rem", display: "flex", alignItems: "center", gap: "0.5rem" }}>
                            <span style={{ fontSize: "1.25rem" }}>🤖</span> AI Recommendation Engine
                        </h3>

                        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "2rem", marginBottom: "1.5rem" }}>
                            <div>
                                <label className="label">Suggested Compensation</label>
                                <div style={{ fontSize: "1.5rem", fontWeight: 700, color: "#10b981" }}>{suggestion.ai_type}</div>
                            </div>
                            <div>
                                <label className="label">Recommended Amount</label>
                                <div style={{ fontSize: "1.5rem", fontWeight: 700 }}>₹{suggestion.ai_amount}</div>
                            </div>
                        </div>

                        <div style={{ marginBottom: "2rem" }}>
                            <label className="label">Resolution Logic</label>
                            <p style={{ fontSize: "0.9rem", color: "var(--color-text-muted)", lineHeight: 1.5 }}>{suggestion.reasoning}</p>
                        </div>

                        <div style={{ display: "flex", gap: "1rem", alignItems: "flex-end" }}>
                            <div style={{ flex: 1 }}>
                                <label className="label">Final Override Amount (₹)</label>
                                <input 
                                    className="input" 
                                    type="number" 
                                    value={overrideAmount}
                                    onChange={(e) => setOverrideAmount(e.target.value)}
                                />
                            </div>
                            <button className="btn-primary" onClick={() => executeRefund("approve")} disabled={loading} style={{ background: "#10b981", height: "3rem", padding: "0 2rem" }}>
                                Approve Refund
                            </button>
                            <button className="btn-secondary" onClick={() => executeRefund("reject")} disabled={loading} style={{ height: "3rem", padding: "0 2rem", color: "#ef4444", borderColor: "#ef4444" }}>
                                Reject
                            </button>
                        </div>
                    </div>
                 )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );

  return (
    <div className="flex h-screen bg-gray-50 text-gray-900 font-display mt-16 overflow-hidden">
        <AdminSidebar isSidebarOpen={isSidebarOpen} setSidebarOpen={setSidebarOpen} />
        <main className="flex-1 overflow-y-auto w-full">
            <NexaAuthWrapper>
                {body()}
            </NexaAuthWrapper>
        </main>
    </div>
  );
}
